from decimal import Decimal
from fractions import Fraction
from typing import Any


def _number(value: Any) -> Fraction:
    """Convert a legacy numeric value to an exact rational number."""
    if value is None or value == "":
        return Fraction(0)

    if isinstance(value, Fraction):
        return value
    if isinstance(value, Decimal):
        return Fraction(value)
    if isinstance(value, int):
        return Fraction(value)
    if isinstance(value, float):
        return Fraction(Decimal(str(value)))

    text = str(value).strip()
    if not text:
        return Fraction(0)
    return Fraction(Decimal(text))


def _id_key(value: Any) -> tuple[int, Any]:
    """Produce a deterministic key for matching and ordering account IDs."""
    if isinstance(value, (int, float, Decimal, Fraction)) and not isinstance(value, bool):
        return (0, _number(value))

    if isinstance(value, str):
        try:
            if value.strip():
                return (0, _number(value))
        except (ValueError, ArithmeticError):
            pass
        return (1, value)

    if value is None:
        return (2, "")

    return (3, f"{type(value).__module__}.{type(value).__qualname__}:{value!s}")


def sweep(
    accounts: list[dict],
    orders: list[dict],
) -> tuple[list[dict], list]:
    """Apply the nightly credit-hold sweep without mutating the inputs."""
    new_accounts = [dict(account) for account in accounts]
    audits: list[tuple[str, Any]] = []

    exposure_by_account: dict[tuple[int, Any], Fraction] = {}
    for order in orders:
        if order.get("DEL_FLG") == "Y" or order.get("STAT_CD") != "I":
            continue

        account_key = _id_key(order.get("ACCT_ID"))
        exposure_by_account[account_key] = (
            exposure_by_account.get(account_key, Fraction(0))
            + _number(order.get("TOT_AMT"))
        )

    eligible_indexes = [
        index
        for index, account in enumerate(new_accounts)
        if account.get("DEL_FLG") != "Y" and account.get("ACCT_TYP") == "C"
    ]
    eligible_indexes.sort(
        key=lambda index: (_id_key(new_accounts[index].get("ACCT_ID")), index)
    )

    for index in eligible_indexes:
        account = new_accounts[index]
        account_id = account.get("ACCT_ID")
        exposure = exposure_by_account.get(_id_key(account_id), Fraction(0))
        credit_limit = _number(account.get("CRED_LIMIT"))

        if exposure > credit_limit and account.get("CRED_HOLD") != "Y":
            account["CRED_HOLD"] = "Y"
            audits.append(("CRED_HOLD_ON", account_id))

        if (
            exposure <= credit_limit * Fraction(8, 10)
            and account.get("CRED_HOLD") == "Y"
        ):
            account["CRED_HOLD"] = "N"
            audits.append(("CRED_HOLD_OFF", account_id))

    return new_accounts, audits
